import { useCallback, useEffect, useRef, useState } from "react";
import { useOrgContext } from "@/hooks/use-org-context";
import { useReferenceSearch } from "@/lib/api/references";
import type { BehaviorSkillOption } from "@/lib/behavior-skills";
import type { LobuRef, LobuRefKind } from "@/lib/references";

/**
 * useMentionSearch — bridges the async React `useReferenceSearch` hook to the
 * imperative `searchRefs(query) => Promise<LobuRef[]>` that a Tiptap suggestion
 * plugin needs. Shared by the chat composer and the behavior prompt editor.
 *
 * A suggestion request sets the query state (driving the search); the promise
 * resolves once results for that exact query are ready — including the
 * "reopened with the same query" case, where no state change fires and the data
 * is already cached, so we resolve from the mirror immediately.
 */
export function useMentionSearch(
	kinds: LobuRefKind[],
	limitPerKind = 5,
	// Agent-scoped data the org-wide search cannot fetch for itself. Only the
	// Behavior composer passes it; see `ReferenceSearchOptions.skills`.
	agentScoped?: { skills?: BehaviorSkillOption[]; skillAgentId?: string | null },
) {
	const { currentOwner, resolvedOrganizationId } = useOrgContext();
	const [query, setQuery] = useState<string | null>(null);
	// Keep the underlying entity/connection/… lists enabled from mount so they're
	// warm before the user types `@`. Gating the fetch on `query !== null` was a
	// lazy-load that made the FIRST `@query` resolve against a cold cache — the
	// data hadn't loaded, so `refs` was `[]` and the popup came up empty. The
	// text filter is applied synchronously in `refs`, so eager-loading the lists
	// costs one small fetch on mount and makes the popup reliable.
	const { refs, isLoading } = useReferenceSearch({
		owner: currentOwner,
		organizationId: resolvedOrganizationId,
		kinds,
		query: query ?? "",
		limitPerKind,
		skills: agentScoped?.skills,
		skillAgentId: agentScoped?.skillAgentId,
	});

	// Live mirrors so the resolver sees fresh values without stale closures.
	const refsRef = useRef<LobuRef[]>([]);
	refsRef.current = refs;
	const loadingRef = useRef(false);
	loadingRef.current = isLoading;
	const queryRef = useRef<string | null>(null);
	queryRef.current = query;

	const pending = useRef<{
		query: string;
		resolve: (refs: LobuRef[]) => void;
	} | null>(null);

	const tryResolve = useCallback(() => {
		const p = pending.current;
		if (!p) return;
		// Wait until the query state reflects this request AND the underlying data
		// has finished loading — otherwise a cold cache (e.g. just after a thread
		// reload) would resolve the pending request with an empty `refs`, leaving
		// the popup permanently empty. `refs` filtering is synchronous, so once the
		// data is present and the query matches, the results are final.
		if (queryRef.current !== p.query) return;
		if (loadingRef.current) return;
		p.resolve(refsRef.current);
		pending.current = null;
	}, []);

	const searchRefs = useCallback(
		(q: string) =>
			new Promise<LobuRef[]>((resolve) => {
				pending.current = { query: q, resolve };
				// Always route through query state. Even when the query text is
				// unchanged, the underlying data may have just arrived, so re-run the
				// resolve check; if the query is new, setQuery kicks the memo + the
				// settle-effect fulfils when refs update.
				if (queryRef.current === q) {
					tryResolve();
				} else {
					setQuery(q);
				}
			}),
		[tryResolve],
	);

	// When the search settles (results/loading/query changed), fulfil any pending
	// request whose query now matches. These deps ARE the trigger — the callback
	// reads them via refs, so biome can't see they must stay in the array.
	// biome-ignore lint/correctness/useExhaustiveDependencies: deps are the intended re-run trigger
	useEffect(() => {
		tryResolve();
	}, [refs, isLoading, query, tryResolve]);

	return searchRefs;
}

