/**
 * A synthetic "write a SQL query" action injected into the suggestion list when
 * the editor is given `onSqlRequest`. It's a `sql` ref with an EMPTY path (no
 * query yet) — picking it opens the SQL dialog instead of inserting a chip. A
 * real SQL chip always has a `#sql=…` path, so the two never collide.
 */
const SQL_ACTION_REF: LobuRef = {
	kind: "sql",
	id: "",
	label: "SQL query",
	path: "",
};

/** True for the synthetic SQL action (empty path) vs. a real SQL chip. */
function isSqlAction(ref: LobuRef): boolean {
	return ref.kind === "sql" && !ref.path;
}

// Extend the Mention node to carry the full ref on its attrs, so renderText /
// renderHTML can rebuild the pill and the serialized token. (addAttributes is a
// node-schema method — it must go through `.extend`, not `.configure`.)
//
// Each attr serializes to a `data-ref-*` on the pill span and parses back from
// it, so a pill survives copy/paste: ProseMirror serializes the selection to
// text/html on copy and re-parses on paste, and without these round-trip rules
// the kind/label/path/id (for SQL, the whole query) would be lost and the chip
// would paste as plain text.
const RefMention = Mention.extend({
	addAttributes() {
		const attr = (name: string) => ({
			default: null,
			parseHTML: (element: HTMLElement) =>
			Text,
			UndoRedo,
			RefMention.configure({
				renderText: ({ node }) =>
					serializeRef({
						kind: (node.attrs.kind as LobuRefKind) ?? "entity",
						id: String(node.attrs.id ?? ""),
						label: String(node.attrs.label ?? ""),
						path: String(node.attrs.path ?? ""),
					}),
				renderHTML: ({ node }) => {
					const kind = (node.attrs.kind as LobuRefKind) ?? "entity";
					const emoji = KIND_EMOJI[kind] ?? "🗄️";
					const isSql = kind === "sql";
					// Serialize every ref attr to a `data-ref-*` (and `data-type="mention"`
					// so the extension's paste rule matches) so a pill — including a SQL
					// chip's full query — round-trips through copy/paste instead of pasting
					// as plain text. addAttributes' parseHTML reads these back.
					const dataAttrs: Record<string, string> = {
						"data-type": "mention",
						"data-ref-kind": kind,
					};
					for (const name of ["id", "label", "path"] as const) {
						const v = node.attrs[name];
						if (v != null) dataAttrs[`data-ref-${name}`] = String(v);
					}
					return [
						"span",
						mergeAttributes(dataAttrs, {
							class: cn(
								"cm-ref-pill inline-flex items-center gap-1 rounded-md bg-accent px-1.5 py-0.5 text-accent-foreground align-baseline",
								// A SQL chip has an edit affordance (click reopens the dialog).
								isSql && "cursor-pointer hover:bg-accent/80",
							),
						}),
						`${emoji} ${node.attrs.label ?? ""}`,
					];
				},
				suggestion,
			}),
		],
		editorProps: {
			attributes: {
				class: "outline-none px-4 pt-3 pb-1 text-sm",
			},
			// Clicking a SQL chip reopens the edit dialog (SQL is the one kind that's
			// authored inline, not navigated to). Other kinds have no click action
			// inside the editor. `nodePos` (4th arg) is the node's START position;
			// `pos` (2nd) is the clicked position, which for an atom can be nodePos+1
			// and would make `onSqlEdit`'s replace target the following node.
			handleClickOn: (_view, _pos, node, nodePos) => {
				if (node.type.name !== "mention") return false;
				if (node.attrs.kind !== "sql") return false;
				const query = sqlQueryFromPath(String(node.attrs.path ?? ""));
				if (query === null) return false;
				cbs.current.onSqlEdit?.(
					{ name: String(node.attrs.label ?? ""), query },
					nodePos,
				);
				return true;
			},
			handleKeyDown: (_view, event) => {
				// Chat composer: Enter submits — BUT only when the @-suggestion popup is
				// closed. While it's open, Enter must fall through to the suggestion
				// plugin so it picks the highlighted mention (our handler runs first as a
				// direct view prop, so we gate on popupOpenRef ourselves). Multi-line
				// editors (submitOnEnter=false) let Enter insert a newline; Shift-Enter
				// always inserts a newline.
				if (
					cbs.current.submitOnEnter &&
					event.key === "Enter" &&
					!event.shiftKey &&
					!popupOpenRef.current
				) {
					event.preventDefault();
					cbs.current.onSubmit();
					return true;
				}
				return false;
			},
		},
		content: markupToDoc(value),
		onUpdate: ({ editor }) => {
			cbs.current.onChange(editor.getText());
		},
	});

	useEffect(() => {
		if (!editor || !handleRef) return;
		handleRef.current = {
			focus: () => editor.commands.focus(),
			clear: () => editor.commands.clearContent(true),
			insertSql: (value, atPos) => {
				const mentionNode = {
					type: "mention",
					attrs: {
						id: value.name,
						label: value.name,
						kind: "sql",
						path: sqlRefPath(value.query),
					},
				};
				if (atPos === undefined) {
					// New chip at the caret, followed by a space.
					editor
						.chain()
		onSubmit: () => void;
		searchRefs: (query: string) => Promise<LobuRef[]>;
		onSqlRequest?: () => void;
		onSqlEdit?: (value: { name: string; query: string }, pos: number) => void;
	}>,
	popupOpenRef: MutableRefObject<boolean>,
): Omit<SuggestionOptions<LobuRef>, "editor"> {
	return {
		char: "@",
		// Await the async search, then prepend the synthetic "SQL query" action
		// when the editor offers SQL and the typed query is a prefix of "sql"
		// (so `@`, `@s`, `@sql` all surface it, but `@feed` doesn't).
		items: async ({ query }) => {
			const refs = await cbs.current.searchRefs(query);
			if (cbs.current.onSqlRequest && "sql".startsWith(query.toLowerCase())) {
				return [SQL_ACTION_REF, ...refs];
			}
			return refs;
		},
		command: ({ editor, range, props }) => {
			// The synthetic SQL action opens the dialog instead of inserting a chip;
			// the typed `@query` is removed first so the editor is clean for insert.
			if (isSqlAction(props)) {
