import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { CodeEditor } from "@/components/ui/code-editor";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

/** The value a SQL source dialog resolves to: an output-field name + raw query. */
export interface SqlSourceValue {
	name: string;
	query: string;
}

/** Guard the message body against an unreasonably large inline query — the
 *  query rides URL-encoded in the token, so a huge SELECT bloats every message
 *  the agent sees. 4 KB is far above any real hand-written query. */
const MAX_SQL_LENGTH = 4096;

interface SqlSourceDialogProps {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	/** Seed values when editing an existing SQL chip; empty when creating. */
	initial?: SqlSourceValue;
	onSubmit: (value: SqlSourceValue) => void;
}

/**
 * The `@sql` authoring surface: a name + a CodeEditor for the raw query. On
 * save it hands back `{ name, query }`; the caller inserts (or updates) a `sql`
 * mention chip whose token carries the query inline (`sqlRefPath`).
 */
export function SqlSourceDialog({
	open,
	onOpenChange,
	initial,
	onSubmit,
}: SqlSourceDialogProps) {
	const [name, setName] = useState("");
	const [query, setQuery] = useState("");
	const [error, setError] = useState<string | null>(null);

	// Re-seed whenever the dialog (re)opens, so edit vs. create start clean.
	useEffect(() => {
		if (!open) return;
		setName(initial?.name ?? "");
		setQuery(initial?.query ?? "");
		setError(null);
	}, [open, initial]);

	const submit = () => {
		const trimmedName = name.trim();
		const trimmedQuery = query.trim();
		if (!trimmedName) {
			setError("Give the SQL source a name.");
			return;
		}
		if (!trimmedQuery) {
			setError("Enter a query.");
			return;
		}
		if (trimmedQuery.length > MAX_SQL_LENGTH) {
			setError(
				`Query is too long (${trimmedQuery.length} chars, max ${MAX_SQL_LENGTH}).`,
			);
			return;
		}
		onSubmit({ name: trimmedName, query: trimmedQuery });
		onOpenChange(false);
	};

	const isEditing = Boolean(initial);

	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogContent className="max-w-2xl">
				<DialogHeader>
					<DialogTitle>
						{isEditing ? "Edit SQL source" : "SQL source"}
					</DialogTitle>
					<DialogDescription>
						Write a query the behavior runs each period. It becomes a reference
						in the prompt — the query travels with the chip.
					</DialogDescription>
				</DialogHeader>
				<div className="space-y-4">
					<div className="space-y-2">
						<Label htmlFor="sql-source-name">Name</Label>
						<Input
							id="sql-source-name"
							value={name}
							onChange={(e) => setName(e.target.value)}
							placeholder="recent_cancellations"
							autoFocus={!isEditing}
						/>
						<p className="text-xs text-muted-foreground">
							The output-field name this source fills.
						</p>
					</div>
					<div className="space-y-2">
						<Label htmlFor="sql-source-query">Query</Label>
						<CodeEditor
							value={query}
							onChange={setQuery}
							language="sql"
							placeholder="SELECT id, payload_text, occurred_at FROM events ORDER BY occurred_at DESC"
							minHeight="160px"
						/>
					</div>
					{error ? <p className="text-sm text-destructive">{error}</p> : null}
				</div>
				<div className="flex justify-end gap-2">
					<Button variant="outline" onClick={() => onOpenChange(false)}>
						Cancel
					</Button>
					<Button onClick={submit}>{isEditing ? "Save" : "Add source"}</Button>
				</div>
			</DialogContent>
		</Dialog>
	);
}

