const SOURCE_KIND_TO_MODE: Record<string, string> = {
	feed: "feed",
	connection: "connection",
	connector: "connector",
	channel: "channel",
	metric: "metric",
};

function sourceName(value: string): string {
	return (
		value
			.trim()
			.toLowerCase()
			.replace(/[^a-z0-9_]+/g, "_")
			.replace(/^_+|_+$/g, "") || "source"
	);
}

/**
 * Append `{name, query}` to `sources` unless the query is already present,
 * uniquifying the derived name with a numeric suffix. Shared by the chip codec
 * and the Behavior sources editor so both name and dedupe identically.
 */
function appendBehaviorSource(
	sources: BehaviorSource[],
	seenQueries: Set<string>,
	usedNames: Set<string>,
	label: string,
	fallback: string,
	query: string,
): void {
	const normalizedQuery = query.trim();
	if (!normalizedQuery || seenQueries.has(normalizedQuery)) return;
	seenQueries.add(normalizedQuery);
	let name = sourceName(label || fallback);
	if (usedNames.has(name)) {
		let suffix = 2;
		while (usedNames.has(`${name}_${suffix}`)) suffix += 1;
		name = `${name}_${suffix}`;
	}
	usedNames.add(name);
	sources.push({ name, query: normalizedQuery });
}

/**
 * The source a single reference stands for, appended to `existing`. Returns
 * `existing` unchanged when the ref carries no query or already appears — the
 * caller can compare lengths to tell whether anything was added.
 */
export function behaviorSourcesWithRef(
	ref: LobuRef,
	existing: BehaviorSource[],
): BehaviorSource[] {
	const sources = [...existing];
	const seenQueries = new Set(existing.map((source) => source.query.trim()));
	const usedNames = new Set(existing.map((source) => source.name));
	if (ref.kind === "sql") {
		const query = sqlQueryFromPath(ref.path);
		if (query) {
			appendBehaviorSource(
				sources,
				seenQueries,
				usedNames,
				ref.label,
				"sql_source",
				query,
			);
		}
		return sources;
	}
	const mode = SOURCE_KIND_TO_MODE[ref.kind];
	const value = ref.id.trim();
	if (mode && value) {
		appendBehaviorSource(
			sources,
			seenQueries,
			usedNames,
			ref.label,
			value,
			`@${mode}:${value}`,
		);
	}
	return sources;
}

/**
 * Derive the source replacement represented by the composer's reference chips.
 * Keep this in sync with the server's create-time prompt derivation.
 */
export function behaviorSourcesFromPrompt(
	text: string,
	explicit: BehaviorSource[] = [],
): BehaviorSource[] {
	const sources = [...explicit];
	const seenQueries = new Set(explicit.map((source) => source.query.trim()));
	const usedNames = new Set(explicit.map((source) => source.name));

	const push = (label: string, fallback: string, query: string) =>
		appendBehaviorSource(
			sources,
			seenQueries,
			usedNames,
			label,
			fallback,
			query,
		);

	for (const match of text.matchAll(REF_TOKEN)) {
		const [, kind, id, label, path] = match;
		if (!kind) continue;
		if (kind === "sql") {
			const query = sqlQueryFromPath(path ?? "");
			if (query) push(label ?? "", "sql_source", query);
			continue;
		}
		const mode = SOURCE_KIND_TO_MODE[kind];
		const value = (id ?? "").trim();
		if (mode && value) push(label ?? "", value, `@${mode}:${value}`);
	}

	return sources;
}

/** A segment of a tokenized body: a verbatim text run or a ref token. */
export type RefSegment =
	| { type: "text"; text: string }
	| { type: "ref"; ref: LobuRef };

/**
 * Split a body into ordered segments — plain text runs interleaved with ref
 * tokens. Pure and allocation-light: used to render sent messages (a stateless
 * pass over the string, no editor instance), so a `@[kind:label](path)` token
 * becomes a pill and everything else stays as text. Unknown kinds pass through
 * as text.
 */
export function tokenizeRefs(text: string): RefSegment[] {
	const segments: RefSegment[] = [];
	let last = 0;
	const re = new RegExp(REF_TOKEN.source, "g");
	let m: RegExpExecArray | null = re.exec(text);

