108		const wantMember = enabled && kinds.includes("member");
109		const wantFeed = enabled && kinds.includes("feed");
110		// `metric` reuses the entity-types list (its declared measures), so it shares
111		// the entities-types query with nothing else here.
112		const wantMetric = enabled && kinds.includes("metric");
113		// `skill` fetches nothing — the caller hands us the agent's library.
114		const wantSkill = enabled && kinds.includes("skill");
115	
116		const wantEntityTree = enabled && (wantEntity || wantMember);
117		const entitiesQ = useEntities(
118			wantEntityTree ? (organizationId ?? undefined) : undefined,
119		);
120		const connectionsQ = useConnections(wantConnection ? organizationId : null);
121		const connectorsQ = useConnectorDefinitions(
122			wantConnector ? organizationId : null,
123		);
124		const behaviorsQ = useBehaviorsList(
125			wantBehavior ? (organizationId ?? undefined) : undefined,
126		);
127		const feedsQ = useAllFeeds(wantFeed ? organizationId : null);
128		const entityTypesQ = useEntityTypes(
129			wantMetric ? (organizationId ?? undefined) : undefined,
130		);
131	
132		const refs = useMemo<LobuRef[]>(() => {
133			if (!owner) return [];
134			const out: LobuRef[] = [];
135			const flatEntities = flattenEntities(entitiesQ.data ?? []);
136	
137			if (wantEntity) {
138				for (const e of flatEntities) {
139					if (e.entity_type === MEMBER_ENTITY_TYPE) continue;
140					if (!matches(e.name, q)) continue;
141					const path = e.path ? buildEntityUrl(owner, e.path) : `/${owner}`;
142					out.push({ kind: "entity", id: String(e.id), path, label: e.name });
143					if (out.filter((r) => r.kind === "entity").length >= limit) break;
144				}
145			}
146	
147			if (wantConnection) {
148				for (const c of connectionsQ.data ?? []) {
149					const label = c.display_name ?? c.connector_name ?? c.connector_key;
150					if (!matches(label, q)) continue;
151					out.push({
152						kind: "connection",
153						id: String(c.id),
154						path: `/${owner}/connectors/${c.connector_key}/${c.id}`,
155						label,
156					});
157					if (out.filter((r) => r.kind === "connection").length >= limit) break;
158				}
159			}
160	
161			if (wantConnector) {
162				for (const d of connectorsQ.data ?? []) {
163					if (!matches(d.name, q)) continue;
164					out.push({
165						kind: "connector",
166						id: d.key,
167						path: `/${owner}/connectors/${d.key}`,
168						label: d.name,
169					});
170					if (out.filter((r) => r.kind === "connector").length >= limit) break;
171				}
172			}
173	
174			if (wantBehavior) {
175				for (const w of behaviorsQ.data ?? []) {
176					if (!matches(w.name, q)) continue;
177					const path = `/${owner}/behaviors/${w.behavior_id}`;
178					out.push({ kind: "behavior", id: w.behavior_id, path, label: w.name });
179					if (out.filter((r) => r.kind === "behavior").length >= limit) break;
180				}
181			}
182	
183			if (wantMember) {
184				for (const e of flatEntities) {
185					if (e.entity_type !== MEMBER_ENTITY_TYPE || !e.path?.length) continue;
186					if (!matches(e.name, q)) continue;
187					out.push({
188						kind: "member",
189						id: String(e.id),
190						path: buildMemoryEntityScopePath(owner, e.path),
191						label: e.name,
192					});
193					if (out.filter((r) => r.kind === "member").length >= limit) break;
194				}
195			}
196	
197			if (wantFeed) {
198				for (const f of feedsQ.data ?? []) {
199					const label = f.display_name || f.feed_key;
200					if (!matches(label, q)) continue;
201					// A feed's source-relevant identifier is its `feed_key` (that's what
202					// `@feed:<key>` compiles against), so we key the ref on it. The path
203					// routes to the feed's connection detail.
204					out.push({
205						kind: "feed",
206						id: f.feed_key,
207						path: `/${owner}/connectors/${f.connector_key}/${f.connection_id}`,
208						label,
209					});
210					if (out.filter((r) => r.kind === "feed").length >= limit) break;
211				}
212			}
213	
214			if (wantMetric) {
215				// Metrics aren't stored objects — they're `<entity_type>.<measure>` pairs
216				// declared on an entity type's metrics_config. The id/label IS the value
217				// (`type.measure`); the path routes to the entity type.
218				for (const et of entityTypesQ.data ?? []) {
219					const measures = et.metrics_config?.measures ?? {};
220					for (const measureName of Object.keys(measures)) {
221						const value = `${et.slug}.${measureName}`;
222						const label = `${et.name || et.slug} · ${measureName}`;
223						if (!matches(`${value} ${label}`, q)) continue;
224						out.push({
225							kind: "metric",
226							id: value,
227							path: `/${owner}/${et.slug}`,
228							label,
229						});
230					}
231					if (out.filter((r) => r.kind === "metric").length >= limit) break;
232				}
233			}
234	
235			if (wantSkill && skillAgentId) {
236				// Only offer skills that can actually be pinned. An entry with no body
237				// would serialize into a chip the server rejects (`assertBehaviorSkills
238				// Resolve`: empty body → 422), so filtering here keeps the popup from
239				// offering a choice that cannot be saved.
240				for (const skill of selectableSkills(skills ?? [])) {
241					if (!matches(`${skill.name} ${skill.description ?? ""}`, q)) continue;
242					out.push({
243						kind: "skill",
244						id: skill.name,
245						path: `/${owner}/agents/${skillAgentId}/skills`,
246						label: skill.name,
247					});
248					if (out.filter((r) => r.kind === "skill").length >= limit) break;
249				}
250			}
251	
252			return out;
253		}, [
254			owner,
255			q,
256			limit,
257			wantEntity,
258			wantConnection,
259			wantConnector,
260			wantBehavior,
261			wantMember,
262			wantFeed,
263			wantMetric,
264			wantSkill,
265			skills,
266			skillAgentId,
267			entitiesQ.data,
268			connectionsQ.data,
269			connectorsQ.data,
270			behaviorsQ.data,
271			feedsQ.data,
272			entityTypesQ.data,
273		]);
274	
275		const isLoading =
276			(wantEntityTree && entitiesQ.isLoading) ||
277			(wantConnection && connectionsQ.isLoading) ||
278			(wantConnector && connectorsQ.isLoading) ||
279			(wantBehavior && behaviorsQ.isLoading) ||
280			(wantFeed && feedsQ.isLoading) ||
281			(wantMetric && entityTypesQ.isLoading);
282	
283		return { refs, isLoading };
284	}
