 *  label so the token stays unambiguous. */
export function serializeRef(ref: LobuRef): string {
	const safeLabel = ref.label.replace(/[[\]]/g, "").trim();
	const safeId = ref.id.replace(/[[\]:]/g, "");
	return `@[${ref.kind}:${safeId}:${safeLabel}](${ref.path})`;
}

