	return (
		value
			.trim()
			.toLowerCase()
			.replace(/[^a-z0-9_]+/g, "_")
			.replace(/^_+|_+$/g, "") || "source"
	);
}

/**
 * Append `{name, query}` to `sources` unless the query is already present,
 * uniquifying the derived name with a numeric suffix. Shared by the chip codec
 * and the Behavior sources editor so both name and dedupe identically.
 */
function appendBehaviorSource(
	sources: BehaviorSource[],
	seenQueries: Set<string>,
	usedNames: Set<string>,
	label: string,
	fallback: string,
	query: string,
): void {
