				for (const measureName of Object.keys(measures)) {
					const value = `${et.slug}.${measureName}`;
					const label = `${et.name || et.slug} · ${measureName}`;
					if (!matches(`${value} ${label}`, q)) continue;
					out.push({
						kind: "metric",
						id: value,
						path: `/${owner}/${et.slug}`,
						label,
					});
