					kind: "skill",
					id: skill.name,
					path: `/${owner}/agents/${skillAgentId}/skills`,
					label: skill.name,
				});
				if (out.filter((r) => r.kind === "skill").length >= limit) break;
			}
		}

		return out;
	}, [
		owner,
		q,
		limit,
		wantEntity,
		wantConnection,
		wantConnector,
		wantBehavior,
		wantMember,
		wantFeed,
		wantMetric,
		wantSkill,
		skills,
		skillAgentId,
		entitiesQ.data,
		connectionsQ.data,
		connectorsQ.data,
		behaviorsQ.data,
		feedsQ.data,
		entityTypesQ.data,
	]);

	const isLoading =
		(wantEntityTree && entitiesQ.isLoading) ||
		(wantConnection && connectionsQ.isLoading) ||
		(wantConnector && connectorsQ.isLoading) ||
		(wantBehavior && behaviorsQ.isLoading) ||
		(wantFeed && feedsQ.isLoading) ||
		(wantMetric && entityTypesQ.isLoading);

	return { refs, isLoading };
}

