/**
 * useReferenceSearch — one cross-type search seam that returns `LobuRef[]` for
 * the reference picker (and, via the picker, the chat @-mention composer).
 *
 * It composes the per-type hooks the app already ships (useEntities,
 * useConnections, useConnectorDefinitions, useBehaviorsList, useAllFeeds,
 * useEntityTypes), normalizes each row to a `LobuRef` with the object's real
 * frontend route, and filters by `kinds` + a fuzzy `query`. This is the
 * command palette's fan-out generalized — the palette, the chat @-mention, and
 * the behavior prompt editor all consume it.
 *
 * `metric` is synthetic: it's an `<entity_type>.<measure>` pair from an entity
 * type's metrics_config, not a stored object (id/label = the value). `event` is
 * still not wired (needs the content-search endpoint).
 */

import { useMemo } from "react";
import { useBehaviorsList } from "@/hooks/use-behaviors";
import {
	type EntityWithChildren,
	useEntities,
	useEntityTypes,
} from "@/lib/api";
import {
	useAllFeeds,
	useConnections,
	useConnectorDefinitions,
} from "@/lib/api/connections";
import { buildMemoryEntityScopePath } from "@/lib/memory-browse";
import {
	type BehaviorSkillOption,
	selectableSkills,
} from "@/lib/behavior-skills";
import type { LobuRef, LobuRefKind } from "@/lib/references";
import { buildEntityUrl } from "@/lib/url";

export interface ReferenceSearchOptions {
	/** Owner slug for building object routes (from useOrgContext().currentOwner). */
	owner: string | null | undefined;
	/** Org id for the underlying list hooks. */
	organizationId: string | null | undefined;
	/** Which object families to include. */
	kinds: LobuRefKind[];
	/** Fuzzy filter over label; empty string returns all (capped by `limit`). */
	query: string;
	/** Max results per kind after filtering. Defaults to 8. */
	limitPerKind?: number;
	/** Gate the network fan-out (e.g. only when the picker/popover is open). */
	enabled?: boolean;
	/**
	 * Skill library for the `skill` kind, supplied by the caller.
	 *
	 * Every other kind here is org-scoped and fetched by this hook. Skills are
	 * AGENT-scoped (`agents.skills_config`), so there is no org-wide list to
	 * fetch and no agent id in these options. The only surface that offers skill
	 * chips is the Behavior composer, which already has the owning agent's
	 * library loaded — it passes it in rather than making this seam
	 * agent-aware.
	 */
	skills?: BehaviorSkillOption[];
	/** Agent whose skills page the chips link to. Required with `skills`. */
	skillAgentId?: string | null;
}

export interface ReferenceSearchResult {
	refs: LobuRef[];
	isLoading: boolean;
}

const DEFAULT_LIMIT = 8;
const MEMBER_ENTITY_TYPE = "$member";

/** Recursively flatten the entity tree, keeping each node's addressing path. */
function flattenEntities(nodes: EntityWithChildren[]): EntityWithChildren[] {
	const out: EntityWithChildren[] = [];
	for (const node of nodes) {
		out.push(node);
		if (node.children?.length) out.push(...flattenEntities(node.children));
	}
	return out;
}

function matches(label: string, q: string): boolean {
	return q === "" || label.toLowerCase().includes(q);
}

export function useReferenceSearch(
	options: ReferenceSearchOptions,
): ReferenceSearchResult {
	const {
		owner,
		organizationId,
		kinds,
		query,
		enabled = true,
		skills,
		skillAgentId,
	} = options;
	const limit = options.limitPerKind ?? DEFAULT_LIMIT;
	const q = query.trim().toLowerCase();

	// Per-kind enable flags as plain booleans, so the memo below has honest
	// primitive dependencies (no closure over `kinds`/`enabled`).
	const wantEntity = enabled && kinds.includes("entity");
	const wantConnection = enabled && kinds.includes("connection");
	const wantConnector = enabled && kinds.includes("connector");
	const wantBehavior = enabled && kinds.includes("behavior");
	const wantMember = enabled && kinds.includes("member");
	const wantFeed = enabled && kinds.includes("feed");
	// `metric` reuses the entity-types list (its declared measures), so it shares
	// the entities-types query with nothing else here.
	const wantMetric = enabled && kinds.includes("metric");
	// `entity_type` is the type itself as a source (`@entity:<slug>` = every row
	// of that type) — it reads the same list `metric` does.
	const wantEntityType = enabled && kinds.includes("entity_type");
	// `skill` fetches nothing — the caller hands us the agent's library.
	const wantSkill = enabled && kinds.includes("skill");

	const wantEntityTree = enabled && (wantEntity || wantMember);
	const entitiesQ = useEntities(
		wantEntityTree ? (organizationId ?? undefined) : undefined,
	);
	const connectionsQ = useConnections(wantConnection ? organizationId : null);
	const connectorsQ = useConnectorDefinitions(
		wantConnector ? organizationId : null,
	);
	const behaviorsQ = useBehaviorsList(
		wantBehavior ? (organizationId ?? undefined) : undefined,
	);
	const feedsQ = useAllFeeds(wantFeed ? organizationId : null);
	const entityTypesQ = useEntityTypes(
		wantMetric || wantEntityType ? (organizationId ?? undefined) : undefined,
	);

	const refs = useMemo<LobuRef[]>(() => {
		if (!owner) return [];
		const out: LobuRef[] = [];
		const flatEntities = flattenEntities(entitiesQ.data ?? []);

		if (wantEntity) {
			for (const e of flatEntities) {
				if (e.entity_type === MEMBER_ENTITY_TYPE) continue;
				if (!matches(e.name, q)) continue;
				const path = e.path ? buildEntityUrl(owner, e.path) : `/${owner}`;
				out.push({ kind: "entity", id: String(e.id), path, label: e.name });
				if (out.filter((r) => r.kind === "entity").length >= limit) break;
			}
		}

		if (wantConnection) {
			for (const c of connectionsQ.data ?? []) {
				const label = c.display_name ?? c.connector_name ?? c.connector_key;
				if (!matches(label, q)) continue;
				out.push({
					kind: "connection",
					id: String(c.id),
					path: `/${owner}/connectors/${c.connector_key}/${c.id}`,
					label,
				});
				if (out.filter((r) => r.kind === "connection").length >= limit) break;
			}
		}

		if (wantConnector) {
			for (const d of connectorsQ.data ?? []) {
				if (!matches(d.name, q)) continue;
				out.push({
					kind: "connector",
					id: d.key,
					path: `/${owner}/connectors/${d.key}`,
					label: d.name,
				});
				if (out.filter((r) => r.kind === "connector").length >= limit) break;
			}
		}

		if (wantBehavior) {
			for (const w of behaviorsQ.data ?? []) {
				if (!matches(w.name, q)) continue;
				const path = `/${owner}/behaviors/${w.behavior_id}`;
				out.push({ kind: "behavior", id: w.behavior_id, path, label: w.name });
				if (out.filter((r) => r.kind === "behavior").length >= limit) break;
			}
		}

		if (wantMember) {
			for (const e of flatEntities) {
				if (e.entity_type !== MEMBER_ENTITY_TYPE || !e.path?.length) continue;
				if (!matches(e.name, q)) continue;
				out.push({
					kind: "member",
					id: String(e.id),
					path: buildMemoryEntityScopePath(owner, e.path),
					label: e.name,
				});
				if (out.filter((r) => r.kind === "member").length >= limit) break;
			}
		}

		if (wantFeed) {
			for (const f of feedsQ.data ?? []) {
				const label = f.display_name || f.feed_key;
				if (!matches(label, q)) continue;
				// A feed's source-relevant identifier is its `feed_key` (that's what
				// `@feed:<key>` compiles against), so we key the ref on it. The path
				// routes to the feed's connection detail.
				out.push({
					kind: "feed",
					id: f.feed_key,
					path: `/${owner}/connectors/${f.connector_key}/${f.connection_id}`,
					label,
				});
				if (out.filter((r) => r.kind === "feed").length >= limit) break;
			}
		}

		if (wantMetric) {
			// Metrics aren't stored objects — they're `<entity_type>.<measure>` pairs
			// declared on an entity type's metrics_config. The id/label IS the value
			// (`type.measure`); the path routes to the entity type.
			for (const et of entityTypesQ.data ?? []) {
				const measures = et.metrics_config?.measures ?? {};
				for (const measureName of Object.keys(measures)) {
					const value = `${et.slug}.${measureName}`;
					const label = `${et.name || et.slug} · ${measureName}`;
					if (!matches(`${value} ${label}`, q)) continue;
					out.push({
						kind: "metric",
						id: value,
						path: `/${owner}/${et.slug}`,
						label,
					});
				}
				if (out.filter((r) => r.kind === "metric").length >= limit) break;
			}
		}

		if (wantSkill && skillAgentId) {
			// Only offer skills that can actually be pinned. An entry with no body
			// would serialize into a chip the server rejects (`assertBehaviorSkills
			// Resolve`: empty body → 422), so filtering here keeps the popup from
			// offering a choice that cannot be saved.
			for (const skill of selectableSkills(skills ?? [])) {
				if (!matches(`${skill.name} ${skill.description ?? ""}`, q)) continue;
				out.push({
					kind: "skill",
					id: skill.name,
					path: `/${owner}/agents/${skillAgentId}/skills`,
					label: skill.name,
				});
				if (out.filter((r) => r.kind === "skill").length >= limit) break;
			}
		}

		return out;
	}, [
		owner,
		q,
		limit,
		wantEntity,
		wantConnection,
		wantConnector,
		wantBehavior,
		wantMember,
		wantFeed,
		wantMetric,
		wantSkill,
		skills,
		skillAgentId,
		entitiesQ.data,
		connectionsQ.data,
		connectorsQ.data,
		behaviorsQ.data,
		feedsQ.data,
		entityTypesQ.data,
	]);

	const isLoading =
		(wantEntityTree && entitiesQ.isLoading) ||
		(wantConnection && connectionsQ.isLoading) ||
		(wantConnector && connectorsQ.isLoading) ||
		(wantBehavior && behaviorsQ.isLoading) ||
		(wantFeed && feedsQ.isLoading) ||
		(wantMetric && entityTypesQ.isLoading);

	return { refs, isLoading };
}

