	"skill",
	"feed",
	"connection",
	"connector",
	"metric",
	"entity_type",
];

interface BehaviorSource {
	name: string;
	query: string;
}

/** An open SQL dialog: `pos` is set when editing an existing chip in place. */
interface SqlDraft {
	initial?: SqlSourceValue;
	pos?: number;
}

