 * The Behavior's instruction surface: one prompt field where skills are
 * referenced inline with `@`.
 *
 * This replaces the ordered skill picker. The picker was the only way to give a
 * Behavior instructions, which meant the author could not say anything of their
 * own — and because the bodies were joined into `prompt` at save time, nothing
 * recorded WHICH skills produced the text, so it could never be diffed or
 * re-pinned. Chips keep the seam: the prompt says what to do, each chip names a
 * skill, and the bodies are stored alongside as snapshots.
 *
 * The strip below the field is deliberately read-only. Attaching and detaching
 * happen in the prompt (type `@`, or delete the chip); a second control that
 * also mutated the set would give two sources of truth for one thing.
 */
export function BehaviorPromptEditor({
	value,
	onChange,
	library,
	pinned,
	required,
	error,
	owner,
	agentId,
	allowSourceRefs = false,
}: {
	value: string;
	onChange: (next: string) => void;
	library: BehaviorSkillOption[];
	/** Snapshots on the version being edited; empty when creating. */
