	// author just deleted stops nagging even though its snapshot is still on the
	// saved version until they hit save.
	const outdated = outdatedPinnedSkills(
		pinned.filter((snapshot) => mentioned.includes(snapshot.name)),
		library,
	);
	const hasSkills = library.length > 0;

	return (
		<div className="space-y-2">
			<div className="flex items-center justify-between gap-3">
				<Label htmlFor="behavior-prompt">
					Instructions{" "}
					{required ? (
						<span className="text-destructive">*</span>
					) : (
						<span className="text-xs font-normal text-muted-foreground">
							(optional)
						</span>
					)}
				</Label>
				{mentioned.length > 0 ? (
					<span className="text-xs text-muted-foreground">
						{mentioned.length}/{MAX_BEHAVIOR_SKILLS} skills
					</span>
				) : null}
			</div>

			<div className="rounded-lg border bg-background focus-within:ring-1 focus-within:ring-ring">
				<MentionEditor
					value={value}
					onChange={onChange}
					// Instructions are multi-line and there is no send action here, so
					// Enter inserts a newline instead of submitting.
					onSubmit={() => {}}
					submitOnEnter={false}
					searchRefs={searchRefs}
					placeholder={
						allowSourceRefs
							? hasSkills
								? "What should this Behavior do? Type @ to pull in a skill or a data source."
								: "What should this Behavior do? Type @ to pull in a data source."
							: hasSkills
								? "What should this Behavior do? Type @ to use a skill."
								: "What should this Behavior do?"
					}
					className="[&_.ProseMirror]:min-h-[7rem] [&_.ProseMirror]:max-h-72 [&_.ProseMirror]:overflow-y-auto"
				/>
			</div>

			{mentioned.length > 0 ? (
				<div className="flex flex-wrap items-center gap-1.5">
					{mentioned.map((name) => {
						const isOutdated = outdated.includes(name);
						const missing = !library.some((skill) => skill.name === name);
						return (
							<Badge
								key={name}
								variant={missing ? "destructive" : "secondary"}
								className="font-normal"
							>
								{name}
								{missing ? " · unavailable" : isOutdated ? " · newer text" : null}
							</Badge>
						);
					})}
				</div>
			) : null}

			{outdated.length > 0 ? (
				// The drift the snapshot model owes the author an answer to: the skill
				// moved on, this Behavior did not. There is no separate "re-pin" action
				// because saving already pins the library's CURRENT text — offering a
				// button that does what Save does would imply they differ.
				<p className="rounded-lg border border-dashed p-3 text-xs text-muted-foreground">
					{outdated.length === 1
