						params={{ owner, agentId }}
						className="font-medium text-foreground underline underline-offset-2"
					>
						Add one
					</Link>{" "}
					to reuse instructions across Behaviors.
				</p>
			) : error ? null : (
				<p className="text-xs text-muted-foreground">
					{hasSkills
						? allowSourceRefs
							? "Type @ to pull in a skill or a data source. Skill text is saved with this version, so later edits to the skill do not change this Behavior until you update it."
							: "Type @ to pull in a skill; its text is saved with this version, so later edits to the skill do not change this Behavior until you update it."
						: allowSourceRefs
							? "Type @ to pull in a feed, connection, connector, or metric this Behavior should read."
							: "Pick an agent to reference its skills."}
				</p>
			)}
		</div>
	);
}

