import { Link } from "@tanstack/react-router";
import { useMemo, useRef, useState } from "react";
import {
	MentionEditor,
	type MentionEditorHandle,
} from "@/components/agents/mention-editor";
import { useMentionSearch } from "@/components/agents/use-mention-search";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
	type BehaviorSkillOption,
	type BehaviorSkillSnapshot,
	MAX_BEHAVIOR_SKILLS,
	outdatedPinnedSkills,
	skillNamesInPrompt,
} from "@/lib/behavior-skills";
import { behaviorSourcesFromPrompt, type LobuRefKind } from "@/lib/references";
import { SqlSourceDialog, type SqlSourceValue } from "./sql-source-dialog";

/** Chip kinds the instructions field offers. `skill` pins text into the
 *  version; the rest compile to Behavior sources (`SOURCE_KIND_TO_MODE`). */
const PROMPT_MENTION_KINDS: LobuRefKind[] = [
	"skill",
	"feed",
	"connection",
	"connector",
	"metric",
	"entity_type",
];

interface BehaviorSource {
	name: string;
	query: string;
}

/** An open SQL dialog: `pos` is set when editing an existing chip in place. */
interface SqlDraft {
	initial?: SqlSourceValue;
	pos?: number;
}

/**
 * The Behavior's instruction surface: one prompt field where skills are
 * referenced inline with `@`.
 *
 * This replaces the ordered skill picker. The picker was the only way to give a
 * Behavior instructions, which meant the author could not say anything of their
 * own — and because the bodies were joined into `prompt` at save time, nothing
 * recorded WHICH skills produced the text, so it could never be diffed or
 * re-pinned. Chips keep the seam: the prompt says what to do, each chip names a
 * skill, and the bodies are stored alongside as snapshots.
 *
 * The strip below the field is deliberately read-only. Attaching and detaching
 * happen in the prompt (type `@`, or delete the chip); a second control that
 * also mutated the set would give two sources of truth for one thing.
 */
export function BehaviorPromptEditor({
	value,
	onChange,
	library,
	pinned,
	required,
	error,
	owner,
	agentId,
	sources,
	onAddSources,
}: {
	value: string;
	onChange: (next: string) => void;
	library: BehaviorSkillOption[];
	/** Snapshots on the version being edited; empty when creating. */
	pinned: BehaviorSkillSnapshot[];
	/** Whether this Behavior runs on its instructions alone. */
	required: boolean;
	error?: string | null;
	owner: string;
	agentId: string;
	/**
	 * Edit only: the assignment's stored `sources[]`, so the field can tell the
	 * author when a chip they just typed is not one of them.
	 *
	 * Create needs neither — `create_behavior` derives `sources[]` from these
	 * very tokens (`extractSourcesFromPromptTokens`), so a chip IS a source the
	 * moment it is saved. `create_version` deliberately does not derive, and it
	 * can't: sources are per-assignment while the version's prompt is shared by
	 * every assignment in the group, so there is no single assignment a shared
	 * prompt's chips could write to. Hence reconcile-and-ask rather than
	 * silently derive.
	 */
	sources?: BehaviorSource[];
	/** Edit only. Given the reconciled list (existing + the prompt's unlinked
	 *  chips) when the author accepts the prompt-drift prompt. */
	onAddSources?: (next: BehaviorSource[]) => void;
}) {
	const searchRefs = useMentionSearch(
		PROMPT_MENTION_KINDS,
		MAX_BEHAVIOR_SKILLS,
		{ skills: library, skillAgentId: agentId || null },
	);
	const editorHandle = useRef<MentionEditorHandle | null>(null);
	const [sqlDraft, setSqlDraft] = useState<SqlDraft | null>(null);

	// Chips in the prompt that this assignment does not carry as a source. Only
	// meaningful on edit; on create `sources` is undefined and the server derives.
	const unlinkedSources = useMemo(() => {
		if (!sources) return [];
		const stored = new Set(sources.map((source) => source.query.trim()));
		return behaviorSourcesFromPrompt(value).filter(
			(source) => !stored.has(source.query.trim()),
		);
	}, [value, sources]);

	const mentioned = skillNamesInPrompt(value);
	// Drift is computed against what the prompt mentions NOW, so a chip the
	// author just deleted stops nagging even though its snapshot is still on the
	// saved version until they hit save.
	const outdated = outdatedPinnedSkills(
		pinned.filter((snapshot) => mentioned.includes(snapshot.name)),
		library,
	);
	const hasSkills = library.length > 0;

	return (
		<div className="space-y-2">
			<div className="flex items-center justify-between gap-3">
				<Label htmlFor="behavior-prompt">
					Instructions{" "}
					{required ? (
						<span className="text-destructive">*</span>
					) : (
						<span className="text-xs font-normal text-muted-foreground">
							(optional)
						</span>
					)}
				</Label>
				{mentioned.length > 0 ? (
					<span className="text-xs text-muted-foreground">
						{mentioned.length}/{MAX_BEHAVIOR_SKILLS} skills
					</span>
				) : null}
			</div>

			<div className="rounded-lg border bg-background focus-within:ring-1 focus-within:ring-ring">
				<MentionEditor
					value={value}
					onChange={onChange}
					// Instructions are multi-line and there is no send action here, so
					// Enter inserts a newline instead of submitting.
					onSubmit={() => {}}
					submitOnEnter={false}
					searchRefs={searchRefs}
					placeholder={
						allowSourceRefs
							? hasSkills
								? "What should this Behavior do? Type @ to pull in a skill or a data source."
								: "What should this Behavior do? Type @ to pull in a data source."
							: hasSkills
								? "What should this Behavior do? Type @ to use a skill."
								: "What should this Behavior do?"
					}
					className="[&_.ProseMirror]:min-h-[7rem] [&_.ProseMirror]:max-h-72 [&_.ProseMirror]:overflow-y-auto"
				/>
			</div>

			{mentioned.length > 0 ? (
				<div className="flex flex-wrap items-center gap-1.5">
					{mentioned.map((name) => {
						const isOutdated = outdated.includes(name);
						const missing = !library.some((skill) => skill.name === name);
						return (
							<Badge
								key={name}
								variant={missing ? "destructive" : "secondary"}
								className="font-normal"
							>
								{name}
								{missing ? " · unavailable" : isOutdated ? " · newer text" : null}
							</Badge>
						);
					})}
				</div>
			) : null}

			{outdated.length > 0 ? (
				// The drift the snapshot model owes the author an answer to: the skill
				// moved on, this Behavior did not. There is no separate "re-pin" action
				// because saving already pins the library's CURRENT text — offering a
				// button that does what Save does would imply they differ.
				<p className="rounded-lg border border-dashed p-3 text-xs text-muted-foreground">
					{outdated.length === 1
						? `"${outdated[0]}" has been edited since this Behavior pinned it.`
						: `${outdated.length} skills have been edited since this Behavior pinned them.`}{" "}
					This Behavior keeps running the pinned text until you save it again.
				</p>
			) : null}

			{error ? <p className="text-xs text-destructive">{error}</p> : null}

			{/*
			 * Shown alongside the error, not instead of it. An empty library and an
			 * unsatisfied instruction requirement co-occur constantly — that is the
			 * blank new-Behavior form — and rendering only the error is what
			 * stranded the first live author: told the draft was invalid, with the
			 * one link that fixes it hidden behind being valid.
			 */}
			{!hasSkills && agentId ? (
				<p className="text-xs text-muted-foreground">
					This agent has no skills yet.{" "}
					<Link
						to="/$owner/agents/$agentId/skills"
						params={{ owner, agentId }}
						className="font-medium text-foreground underline underline-offset-2"
					>
						Add one
					</Link>{" "}
					to reuse instructions across Behaviors.
				</p>
			) : error ? null : (
				<p className="text-xs text-muted-foreground">
					{hasSkills
						? allowSourceRefs
							? "Type @ to pull in a skill or a data source. Skill text is saved with this version, so later edits to the skill do not change this Behavior until you update it."
							: "Type @ to pull in a skill; its text is saved with this version, so later edits to the skill do not change this Behavior until you update it."
						: allowSourceRefs
							? "Type @ to pull in a feed, connection, connector, or metric this Behavior should read."
							: "Pick an agent to reference its skills."}
				</p>
			)}
		</div>
	);
}

