it("keeps Sources out of the primary create flow but still reachable", () => {
	// On create the server derives `sources[]` from the prompt's `@` chips, so
	// a top-level editor for the same thing is duplication. It stays under
	// Advanced for what chips cannot express (raw SQL).
	render(<FromScratchPanel {...baseProps} triggers={SCHEDULE} />);

	const advanced = document.getElementById("behavior-advanced-settings");
	const addSource = screen.getByRole("button", { name: /Add source/ });
	expect(advanced?.contains(addSource)).toBe(true);
	// Collapsed by default, so it is not competing with the primary fields.
	expect(advanced?.className).toContain("hidden");
	// Create is the surface where prompt chips DO become sources.
	expect(screen.getByText(/with @ in the instructions adds one too/i))
		.toBeTruthy();
});

it("keeps Sources top-level on edit, where the save cannot derive them", () => {
	// `create_version` deliberately does not derive from the prompt, so this
	// editor IS the only way to change an existing Behavior's sources.
	render(<FromScratchPanel {...baseProps} triggers={SCHEDULE} isEditing />);

	const advanced = document.getElementById("behavior-advanced-settings");
