it("gives create no sources editor at all — `@` is the whole gesture", () => {
	// The server derives `sources[]` from the prompt's `@` chips, SQL included
	// (the menu's "SQL query" action writes a chip carrying the query), so a
	// second editor has nothing left to express. It is gone, not hidden: a
	// collapsed duplicate is still two places to author one thing.
	render(<FromScratchPanel {...baseProps} triggers={SCHEDULE} />);

	expect(screen.queryByRole("button", { name: /Add source/ })).toBeNull();
	expect(screen.queryByRole("button", { name: /Add SQL/ })).toBeNull();
	const advanced = document.getElementById("behavior-advanced-settings");
	expect(advanced?.textContent).not.toContain("Sources");
	// The instructions field advertises the sources it can now author.
	expect(screen.getByText(/Type @ to pull in/i)).toBeTruthy();
});

