70	function assertSafeRefValue(label: string, value: string): string {
71	  const trimmed = value.trim();
72	  if (!trimmed) throw new Error(`${label} reference is empty`);
73	  if (!SAFE_REF_VALUE_RE.test(trimmed)) {
