import { describe, expect, it } from "vitest";
import {
	behaviorSourcesFromPrompt,
	hasRefs,
	isSqlRefPath,
	type LobuRef,
	parseRefs,
	serializeRef,
	sqlQueryFromPath,
	sqlRefPath,
	stripRefs,
	tokenizeRefs,
} from "./references";

const entityRef: LobuRef = {
	kind: "entity",
	id: "42",
	path: "/acme/company/spotify",
	label: "Spotify",
};

const connRef: LobuRef = {
	kind: "connection",
	id: "7",
	path: "/acme/connectors/stripe/7",
	label: "Stripe prod",
};

describe("serializeRef", () => {
	it("produces an inline token with kind, id, label, path", () => {
		expect(serializeRef(entityRef)).toBe(
			"@[entity:42:Spotify](/acme/company/spotify)",
		);
	});

	it("strips brackets from the label so the token stays unambiguous", () => {
		expect(serializeRef({ ...entityRef, label: "Spo[ti]fy" })).toBe(
			"@[entity:42:Spotify](/acme/company/spotify)",
		);
	});
});

describe("parseRefs", () => {
	it("round-trips a serialized ref including the id", () => {
		const parsed = parseRefs(`look at ${serializeRef(entityRef)} please`);
		expect(parsed).toHaveLength(1);
		expect(parsed[0]).toMatchObject({
			kind: "entity",
			id: "42",
			label: "Spotify",
			path: "/acme/company/spotify",
		});
	});

	it("parses multiple refs in order", () => {
		const parsed = parseRefs(
			`${serializeRef(entityRef)} and ${serializeRef(connRef)}`,
		);
		expect(parsed.map((r) => r.kind)).toEqual(["entity", "connection"]);
		expect(parsed.map((r) => r.path)).toEqual([entityRef.path, connRef.path]);
	});

	it("skips unknown kinds without throwing", () => {
		expect(parseRefs("@[bogus:X](/a/b)")).toEqual([]);
	});

	it("ignores arbitrary bracket text that is not a ref token", () => {
		expect(parseRefs("an array[0] and a [link](http://x)")).toEqual([]);
	});
});

describe("behaviorSourcesFromPrompt", () => {
	it("derives source refs while excluding non-source chips", () => {
		const prompt = [
			"@[entity:42:Spotify](/acme/company/spotify)",
			"@[feed:issues:GitHub Issues](/acme/feeds/issues)",
			"@[connection:7:GitHub Issues](/acme/connectors/github/7)",
			"@[metric:company.churn:Churn](/acme/company/churn)",
		].join(" ");

		expect(behaviorSourcesFromPrompt(prompt)).toEqual([
			{ name: "github_issues", query: "@feed:issues" },
			{ name: "github_issues_2", query: "@connection:7" },
			{ name: "churn", query: "@metric:company.churn" },
		]);
	});

	it("decodes SQL and preserves explicit sources while replacing chip sources", () => {
		const query = "SELECT id FROM events WHERE payload_type = 'new'";
		const prompt = serializeRef({
			kind: "sql",
			id: "recent",
			label: "Recent",
			path: sqlRefPath(query),
		});

		expect(
			behaviorSourcesFromPrompt(prompt, [
				{ name: "curated", query: "@feed:curated" },
			]),
		).toEqual([
			{ name: "curated", query: "@feed:curated" },
			{ name: "recent", query },
		]);
	});
});

describe("hasRefs", () => {
	it("is stateless across calls", () => {
		const text = serializeRef(entityRef);
		expect(hasRefs(text)).toBe(true);
		expect(hasRefs(text)).toBe(true);
		expect(hasRefs("no refs here")).toBe(false);
	});
});

describe("stripRefs", () => {
	it("replaces tokens with the label by default", () => {
		expect(stripRefs(`see ${serializeRef(entityRef)}`)).toBe("see Spotify");
	});

	it("accepts a custom renderer", () => {
		expect(stripRefs(serializeRef(entityRef), (r) => r.path)).toBe(
			"/acme/company/spotify",
		);
	});
});

describe("sql ref payload", () => {
	// A real query with the exact chars that would break an unencoded token:
	// spaces, parens (via now()), a `>` and quotes.
	const query = "SELECT id FROM events WHERE ts > now() - interval '7 days'";

	it("round-trips a query through path encode/decode", () => {
		const path = sqlRefPath(query);
		expect(sqlQueryFromPath(path)).toBe(query);
	});

	it("encodes so the token's path group survives parse (no space/paren)", () => {
		const path = sqlRefPath(query);
		expect(path.startsWith("#sql=")).toBe(true);
		expect(path).not.toMatch(/[\s)]/);
	});

	it("survives a full serialize → parse round-trip as a self-contained token", () => {
		const ref: LobuRef = {
			kind: "sql",
			id: "recent",
			label: "Recent events",
			path: sqlRefPath(query),
		};
		const token = serializeRef(ref);
		const parsed = parseRefs(`watch ${token} daily`);
		expect(parsed).toHaveLength(1);
		expect(parsed[0]?.kind).toBe("sql");
		expect(sqlQueryFromPath(parsed[0]?.path ?? "")).toBe(query);
	});

	it("isSqlRefPath distinguishes payloads from routes", () => {
		expect(isSqlRefPath(sqlRefPath(query))).toBe(true);
		expect(isSqlRefPath("/acme/company/spotify")).toBe(false);
	});

	it("sqlQueryFromPath returns null for a non-SQL path", () => {
		expect(sqlQueryFromPath("/acme/company/spotify")).toBeNull();
	});
});

describe("tokenizeRefs", () => {
	it("splits text into ordered text + ref segments", () => {
		const segs = tokenizeRefs(
			"hi @[entity:42:Spotify](/acme/company/spotify) there",
		);
		expect(segs).toEqual([
			{ type: "text", text: "hi " },
			{
				type: "ref",
				ref: {
					kind: "entity",
					id: "42",
					label: "Spotify",
					path: "/acme/company/spotify",
				},
			},
			{ type: "text", text: " there" },
		]);
	});

	it("returns a single text segment when there are no refs", () => {
		expect(tokenizeRefs("plain text")).toEqual([
			{ type: "text", text: "plain text" },
		]);
	});

	it("handles back-to-back refs with no text between", () => {
		const segs = tokenizeRefs(
			"@[entity:1:A](/o/company/a)@[connection:2:B](/o/connectors/x/1)",
		);
		expect(segs.map((s) => s.type)).toEqual(["ref", "ref"]);
	});

	it("keeps unknown kinds as text (never a ref segment)", () => {
		expect(tokenizeRefs("@[bogus:X](/a)")).toEqual([
			{ type: "text", text: "@[bogus:X](/a)" },
		]);
	});
});

