/**
 * Ref helpers for the SPA.
 *
 * The grammar itself — the token regex, the kind list, serialize/parse, the SQL
 * payload codec, and the Behavior source compilation — lives ONCE in
 * `@lobu/core/refs`, imported here and by the server. It used to be typed out
 * separately on each side and kept in sync by hand; adding a kind whose name
 * contains `_` broke the copy nobody remembered to widen, silently, because an
 * unmatched token yields `[]` rather than an error.
 *
 * What stays here is only what the browser needs and the server does not:
 * turning a body into renderable segments.
 *
 * Imported from the `/refs` subpath, never the `@lobu/core` root — the root is
 * CJS and drags Node globals into the bundle (`scripts/check-no-core-barrel.mjs`).
 */

export {
	type BehaviorSource,
	behaviorSourcesFromPrompt,
	behaviorSourcesWithRef,
	isLobuRefKind,
	isSqlRefPath,
	type LobuRef,
	type LobuRefKind,
	LOBU_REF_KINDS,
	parseRefs,
	REF_TOKEN,
	serializeRef,
	skillNamesFromPrompt,
	SOURCE_KIND_TO_MODE,
	sqlQueryFromPath,
	sqlRefPath,
	stripRefTokens,
} from "@lobu/core/refs";

import {
	isLobuRefKind,
	type LobuRef,
	type LobuRefKind,
	REF_TOKEN,
} from "@lobu/core/refs";

/** A segment of a tokenized body: a verbatim text run or a ref token. */
export type RefSegment =
	| { type: "text"; text: string }
	| { type: "ref"; ref: LobuRef };

/**
 * Split a body into ordered segments — plain text runs interleaved with ref
 * tokens. Pure and allocation-light: used to render sent messages (a stateless
 * pass over the string, no editor instance), so a `@[kind:id:label](path)` token
 * becomes a pill and everything else stays as text. Unknown kinds pass through
 * as text.
 */
export function tokenizeRefs(text: string): RefSegment[] {
	const segments: RefSegment[] = [];
	let last = 0;
	const re = new RegExp(REF_TOKEN.source, "g");
	let m: RegExpExecArray | null = re.exec(text);
	while (m !== null) {
		const [raw, kind, id, label, path] = m;
		const idx = m.index;
		if (kind && isLobuRefKind(kind) && path) {
			if (idx > last)
				segments.push({ type: "text", text: text.slice(last, idx) });
			segments.push({
				type: "ref",
				ref: {
					kind: kind as LobuRefKind,
					id: id ?? "",
					label: (label ?? "").trim(),
					path,
				},
			});
			last = idx + raw.length;
		}
		m = re.exec(text);
	}
	if (last < text.length)
		segments.push({ type: "text", text: text.slice(last) });
	return segments;
}

