		expect(out).toEqual([
			{ name: "issues", query: "@feed:k1" },
			{ name: "issues_2", query: "@feed:k2" },
		]);
	});

	it("returns [] for a prompt with no source tokens", () => {
		expect(behaviorSourcesFromPrompt("just plain instructions")).toEqual(
			[],
		);
	});
});

