/**
 * Behavior skill pinning — the web mirror of `lobu apply`.
 *
 * A Behavior's instructions are its `prompt` (the author's task statement) plus
 * the bodies of the skills it pins. Skills are referenced INLINE, as `@[skill:…]`
 * chips in the prompt; this module turns those chips into the
 * `skills[{name, content}]` array the API stores on the version.
 *
 * The array is what gets stored and delivered (as `.skills/<name>/SKILL.md`);
 * the chip is how the author names it. They must agree, and the server refuses
 * the write when they don't (`assertPromptSkillTokensPinned`) — an unpinned chip
 * would otherwise survive into the instructions as literal `@[skill:…]` text
 * with no file behind it.
 *
 * Bodies are SNAPSHOTTED at save time: editing a skill afterwards does not
 * change an existing Behavior until it is saved again. That is deliberate — a
 * Behavior should not silently change what it does because a shared skill was
 * edited — and `outdatedPinnedSkills` is what surfaces the drift so the author
 * can take the new text on purpose.
 */

import { parseRefs } from "@/lib/references";

/** Max skills a Behavior may pin. Mirrors `MAX_BEHAVIOR_SKILLS` (CLI + server). */
export const MAX_BEHAVIOR_SKILLS = 5;

/** Pinned-body ceiling in bytes. Mirrors the server's 32KB cap. */
export const MAX_PINNED_SKILL_BYTES = 32 * 1024;

/** A skill the composer can offer: a library entry with a usable body. */
export interface BehaviorSkillOption {
	name: string;
	description?: string;
	/**
	 * Authored body. Custom skills carry `content`; bundled/system skills carry
	 * the catalog's `instructions`. The CLI only ever resolves files into
	 * `content`, so it has no equivalent fallback.
	 */
	content?: string;
	instructions?: string;
	enabled: boolean;
}

/** One pinned snapshot, exactly as the API stores it. */
export interface BehaviorSkillSnapshot {
	name: string;
	content: string;
}

/** The body a skill contributes, or "" when it has none. */
export function skillBody(skill: BehaviorSkillOption): string {
	return (skill.content ?? skill.instructions ?? "").trim();
}

/** Skills that can actually be pinned: enabled and carrying a body. */
export function selectableSkills(
	library: BehaviorSkillOption[],
): BehaviorSkillOption[] {
	return library.filter((skill) => skill.enabled && skillBody(skill) !== "");
}

/** Trigger shape this module needs. Extra keys are ignored. */
export interface BehaviorTriggerLike {
	kind?: string;
	execution?: string;
}

/**
 * Whether the Behavior runs on its own instructions alone.
 *
 * An event trigger executing as "turn" carries its own content (the incoming
 * message/event) and may run with no instructions at all, on the built-in
 * default. Everything else — schedule triggers, event triggers with execution
 * "window", and Behaviors with no triggers (manual runs) — has nothing but its
 * instructions. Mirrors the server's `behaviorRequiresInstructions`.
 */
export function behaviorRequiresInstructions(
	triggers: BehaviorTriggerLike[] | undefined,
): boolean {
	const list = triggers ?? [];
	if (list.length === 0) return true;
	return list.some(
		(trigger) => trigger.kind === "schedule" || trigger.execution === "window",
	);
}

/** Skill names referenced by `@[skill:…]` chips, de-duped, in first-seen order. */
export function skillNamesInPrompt(prompt: string): string[] {
	const seen = new Set<string>();
	const names: string[] = [];
	for (const ref of parseRefs(prompt)) {
		if (ref.kind !== "skill") continue;
		const name = ref.id.trim();
		if (!name || seen.has(name)) continue;
		seen.add(name);
		names.push(name);
	}
	return names;
}

/**
 * Resolve the prompt's skill chips into the snapshots to store.
 *
 * Chips whose skill is missing or bodiless are dropped rather than throwing —
 * `validateBehaviorPrompt` is what blocks the save, so this stays total and the
 * caller never has to guard it.
 */
export function resolveSkillSnapshots(
	prompt: string,
	library: BehaviorSkillOption[],
): BehaviorSkillSnapshot[] {
	const byName = new Map(library.map((skill) => [skill.name, skill]));
	const snapshots: BehaviorSkillSnapshot[] = [];
	for (const name of skillNamesInPrompt(prompt)) {
		const skill = byName.get(name);
		if (!skill) continue;
		const body = skillBody(skill);
		if (!body) continue;
		snapshots.push({ name, content: body });
	}
	return snapshots;
}

/** UTF-8 byte length of the pinned bodies (the cap is bytes, not characters). */
export function pinnedByteLength(snapshots: BehaviorSkillSnapshot[]): number {
	const encoder = new TextEncoder();
	return snapshots.reduce(
		(sum, snapshot) => sum + encoder.encode(snapshot.content).length,
		0,
	);
}

