1	/**
2	 * Tests for the shared ref-token codec.
3	 *
4	 * This module is consumed by BOTH the server (`watchers/source-refs.ts`) and
5	 * the SPA (`owletto/src/lib/references.ts`). Before consolidation each side
6	 * carried its own transcription of the grammar, and the failure mode of a
7	 * mismatch is silent: a token the regex does not match is skipped, so the
8	 * caller receives `[]` and never an error. The kind-group cases below are the
9	 * regression guard for exactly that.
10	 */
11	
12	import { describe, expect, it } from "bun:test";
13	import {
14	  behaviorSourcesFromPrompt,
15	  behaviorSourcesWithRef,
16	  mergePromptSources,
17	  parseRefs,
18	  serializeRef,
19	  skillNamesFromPrompt,
20	  sqlQueryFromPath,
21	  sqlRefPath,
22	  stripRefTokens,
23	} from "../refs";
24	
25	describe("ref token grammar", () => {
26	  it("round-trips a ref through serialize and parse", () => {
27	    const ref = {
28	      kind: "feed" as const,
29	      id: "issues",
30	      label: "GitHub Issues",
31	      path: "/acme/connectors/github/7",
32	    };
33	    expect(parseRefs(serializeRef(ref))).toEqual([ref]);
34	  });
35	
36	  it("lexes a kind containing an underscore", () => {
37	    // Narrowing the kind group to [a-z]+ makes this return [] rather than
38	    // throwing, which is how an entire chip kind disappears unnoticed.
39	    const parsed = parseRefs("@[entity_type:company:Companies](/acme/company)");
40	    expect(parsed).toHaveLength(1);
41	    expect(parsed[0]?.kind).toBe("entity_type");
42	    expect(parsed[0]?.id).toBe("company");
43	  });
44	
45	  it("strips every token kind, underscored ones included", () => {
46	    const prompt =
47	      "watch @[entity_type:company:Companies](/acme/company) and " +
48	      "@[feed:issues:Issues](/acme/f) closely";
