import { Plus, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { CommandItem } from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import { useOrgContext } from "@/hooks/use-org-context";
import { useReferenceSearch } from "@/lib/api/references";
import { behaviorSourcesWithRef, type LobuRefKind } from "@/lib/references";

/**
 * Object kinds that can back a Behavior source. Every kind listed here must
 * have a mapping in `SOURCE_KIND_TO_MODE` (`lib/references.ts`), or picking one
 * closes the popover and silently adds nothing — `behavior-sources-editor.test.ts`
 * asserts that for the whole list.
 *
 * No `entity`. An entity reference scopes the Behavior, it is not a source (the
 * same exclusion the server's `PROMPT_KIND_TO_MODE` makes). `entity_type` is
 * the one that belongs here: it carries the type *slug* the server's
 * `@entity:<slug>` grammar expects, where an `entity` ref would send an
 * instance id.
 */
export const SOURCE_KINDS: LobuRefKind[] = [
	"connection",
	"connector",
	"feed",
	"metric",
	"entity_type",
];

export interface BehaviorSource {
	name: string;
	query: string;
}

/**
 * The Behavior's data sources, authored on their own.
 *
 * Sources used to be a side effect of `@`-chips in the goal field. #2320 takes
 * the goal away (instructions are compiled skills now), and sources stay
 * Behavior-owned — skills never author them — so they need a surface of their
 * own rather than disappearing with the prompt.
 */
export function BehaviorSourcesEditor({
	sources,
	onChange,
	disabled,
}: {
	sources: BehaviorSource[];
	onChange: (next: BehaviorSource[]) => void;
	disabled?: boolean;
}) {
	const { currentOwner, resolvedOrganizationId } = useOrgContext();
	const [query, setQuery] = useState("");

	const { refs } = useReferenceSearch({
		owner: currentOwner,
		organizationId: resolvedOrganizationId,
		kinds: SOURCE_KINDS,
		query,
		limitPerKind: 10,
	});


	return (
		<div className="space-y-2">
			<Label>Sources</Label>

			{sources.length > 0 ? (
				<ul className="space-y-2">
					{sources.map((source) => (
						<li
							key={source.query}
							className="flex items-start gap-2 rounded-lg border bg-background p-2"
						>
							<div className="min-w-0 flex-1">
								<div className="truncate font-mono text-xs font-medium">
									{source.name}
								</div>
								<div className="truncate text-xs text-muted-foreground">
									{source.query}
								</div>
							</div>
							<Button
								type="button"
								variant="ghost"
								size="icon"
								className="h-7 w-7 shrink-0"
								aria-label={`Remove source ${source.name}`}
								disabled={disabled}
								onClick={() =>
									onChange(sources.filter((s) => s.query !== source.query))
								}
							>
								<X className="h-3.5 w-3.5" />
							</Button>
						</li>
					))}
				</ul>
			) : null}

			<div className="flex gap-2">
				<Combobox
					searchPlaceholder="Search feeds, connections, metrics…"
					emptyText="No matching reference."
					onQueryChange={setQuery}
					trigger={() => (
						<Button
							type="button"
							variant="outline"
							size="sm"
							disabled={disabled}
						>
							<Plus className="mr-2 h-3.5 w-3.5" />
							Add source
						</Button>
					)}
				>
					{(close) =>
						refs.map((ref) => (
							<CommandItem
								key={`${ref.kind}:${ref.id}`}
								value={`${ref.label} ${ref.kind}`}
								onSelect={() => {
									onChange(behaviorSourcesWithRef(ref, sources));
									close();
								}}
							>
								<span className="truncate text-sm">{ref.label}</span>
								<span className="ml-2 shrink-0 text-xs text-muted-foreground">
									{ref.kind}
								</span>
							</CommandItem>
						))
					}
				</Combobox>

			</div>

			<p className="text-xs text-muted-foreground">
				Data handed to the agent alongside its instructions, and what change
				detection is measured against. Editing a Behavior does not re-read the
				instructions for these — this list is what runs. To add a SQL source,
				write it with @ in the instructions above. Behavior-owned; skills never
				add or remove sources.
			</p>

		</div>
	);
}

/**
 * Tests for the shared ref-token codec.
 *
 * This module is consumed by BOTH the server (`watchers/source-refs.ts`) and
 * the SPA (`owletto/src/lib/references.ts`). Before consolidation each side
 * carried its own transcription of the grammar, and the failure mode of a
 * mismatch is silent: a token the regex does not match is skipped, so the
 * caller receives `[]` and never an error. The kind-group cases below are the
 * regression guard for exactly that.
 */

import { describe, expect, it } from "bun:test";
import {
  behaviorSourcesFromPrompt,
  behaviorSourcesWithRef,
  mergePromptSources,
  parseRefs,
  serializeRef,
  skillNamesFromPrompt,
  sqlQueryFromPath,
  sqlRefPath,
  stripRefTokens,
} from "../refs";

describe("ref token grammar", () => {
  it("round-trips a ref through serialize and parse", () => {
    const ref = {
      kind: "feed" as const,
      id: "issues",
      label: "GitHub Issues",
      path: "/acme/connectors/github/7",
    };
    expect(parseRefs(serializeRef(ref))).toEqual([ref]);
  });

  it("lexes a kind containing an underscore", () => {
    // Narrowing the kind group to [a-z]+ makes this return [] rather than
    // throwing, which is how an entire chip kind disappears unnoticed.
    const parsed = parseRefs("@[entity_type:company:Companies](/acme/company)");
    expect(parsed).toHaveLength(1);
    expect(parsed[0]?.kind).toBe("entity_type");
    expect(parsed[0]?.id).toBe("company");
  });

  it("strips every token kind, underscored ones included", () => {
    const prompt =
      "watch @[entity_type:company:Companies](/acme/company) and " +
      "@[feed:issues:Issues](/acme/f) closely";
    expect(stripRefTokens(prompt)).toBe("watch   and   closely");
  });

  it("skips unknown kinds instead of throwing", () => {
    expect(parseRefs("@[nonsense:1:X](/a) @[feed:k:F](/b)")).toHaveLength(1);
  });
});

describe("sql payload codec", () => {
  it("survives parens, quotes and newlines through the token path group", () => {
    const query =
      "SELECT id\nFROM events\nWHERE ts > now() - interval '7 days'";
    const path = sqlRefPath(query);
    expect(path).not.toContain(")");
    expect(path).not.toContain(" ");
    expect(sqlQueryFromPath(path)).toBe(query);
  });

  it("returns null for a navigable path", () => {
    expect(sqlQueryFromPath("/acme/company/spotify")).toBeNull();
  });
});

describe("behaviorSourcesFromPrompt", () => {
  it("compiles entity_type to the @entity: type-slug mode", () => {
    expect(
      behaviorSourcesFromPrompt(
        "@[entity_type:company:Companies](/acme/company)"
      )
    ).toEqual([{ name: "companies", query: "@entity:company" }]);
  });

  it("excludes an entity INSTANCE while including the type", () => {
    const prompt =
      "@[entity:42:Spotify](/acme/company/spotify) " +
      "@[entity_type:company:Companies](/acme/company)";
    expect(behaviorSourcesFromPrompt(prompt)).toEqual([
      { name: "companies", query: "@entity:company" },
    ]);
  });

  it("decodes a sql chip and de-dupes by query with unique names", () => {
    const query = "SELECT id FROM events";
    const prompt = [
      "@[feed:k1:Issues](/a)",
      "@[feed:k1:Issues again](/a)",
      "@[feed:k2:Issues](/b)",
      `@[sql:recent:Recent](${sqlRefPath(query)})`,
    ].join(" ");
    expect(behaviorSourcesFromPrompt(prompt)).toEqual([
      { name: "issues", query: "@feed:k1" },
      { name: "issues_2", query: "@feed:k2" },
      { name: "recent", query },
    ]);
  });

  it("never treats a skill chip as a source", () => {
    expect(behaviorSourcesFromPrompt("@[skill:triage:triage](/a)")).toEqual([]);
    expect(skillNamesFromPrompt("@[skill:triage:triage](/a)")).toEqual([
      "triage",
    ]);
  });
});

describe("behaviorSourcesWithRef", () => {
  it("appends an entity_type ref and leaves an existing duplicate alone", () => {
    const first = behaviorSourcesWithRef(
      {
        kind: "entity_type",
        id: "company",
        label: "Companies",
        path: "/acme/company",
      },
      []
    );
    expect(first).toEqual([{ name: "companies", query: "@entity:company" }]);

    const again = behaviorSourcesWithRef(
      {
        kind: "entity_type",
        id: "company",
        label: "Companies",
        path: "/acme/company",
      },
      first
    );
    expect(again).toEqual(first);
  });
});

describe("mergePromptSources", () => {
  it("keeps explicit sources first and suffixes colliding prompt names", () => {
    expect(
      mergePromptSources(
        [{ name: "slack", query: "@feed:a" }],
        [
          { name: "slack", query: "@connection:7" },
          { name: "dupe", query: "@feed:a" },
        ]
      )
    ).toEqual([
      { name: "slack", query: "@feed:a" },
      { name: "slack_2", query: "@connection:7" },
    ]);
  });
});

import { describe, expect, it } from "vitest";
import {
	type BehaviorSkillOption,
	type BehaviorSkillSnapshot,
	behaviorRequiresInstructions,
	MAX_BEHAVIOR_SKILLS,
	MAX_PINNED_SKILL_BYTES,
	outdatedPinnedSkills,
	pinnedByteLength,
	resolveSkillSnapshots,
	selectableSkills,
	skillNamesInPrompt,
	validateBehaviorPrompt,
} from "./behavior-skills";

const skill = (
	name: string,
	over: Partial<BehaviorSkillOption> = {},
): BehaviorSkillOption => ({
	name,
	content: `body of ${name}`,
	enabled: true,
	...over,
});

const LIBRARY = [skill("triage"), skill("sql-style"), skill("digest")];

/** A skill chip exactly as the composer serializes it. */
const chip = (name: string, label = name) =>
	`@[skill:${name}:${label}](/acme/agents/a/skills)`;

const schedule = [{ kind: "schedule" }];
const turn = [{ kind: "event", execution: "turn" }];

describe("skillNamesInPrompt", () => {
	it("reads the chip's id, not its label", () => {
		expect(skillNamesInPrompt(`Run ${chip("triage", "Triage inbox")} daily`)).toEqual(
			["triage"],
		);
	});

	it("ignores non-skill chips", () => {
		expect(
			skillNamesInPrompt(
				"@[feed:inbox:Inbox](/acme/feeds/inbox) @[entity:1:Acme](/acme)",
			),
		).toEqual([]);
	});

	it("de-dupes but keeps first-seen order", () => {
		expect(
			skillNamesInPrompt(`${chip("b")} ${chip("a")} ${chip("b")}`),
		).toEqual(["b", "a"]);
	});
});

describe("resolveSkillSnapshots", () => {
	it("pins the library body for each mentioned skill", () => {
		expect(
			resolveSkillSnapshots(`Do ${chip("triage")} then ${chip("digest")}`, LIBRARY),
		).toEqual([
			{ name: "triage", content: "body of triage" },
			{ name: "digest", content: "body of digest" },
		]);
	});

	it("falls back to a bundled skill's instructions", () => {
		const bundled = [
			{ name: "sys", instructions: "bundled body", enabled: true },
		];
		expect(resolveSkillSnapshots(chip("sys"), bundled)).toEqual([
			{ name: "sys", content: "bundled body" },
		]);
	});

	it("drops a chip with no library entry rather than throwing", () => {
		// validateBehaviorPrompt is what blocks the save; this stays total so no
		// caller has to guard it.
		expect(resolveSkillSnapshots(chip("gone"), LIBRARY)).toEqual([]);
	});

	it("returns nothing for a prompt with no chips", () => {
		expect(resolveSkillSnapshots("Summarize yesterday.", LIBRARY)).toEqual([]);
	});
});

describe("behaviorRequiresInstructions", () => {
	it("requires them with no triggers at all", () => {
		expect(behaviorRequiresInstructions([])).toBe(true);
		expect(behaviorRequiresInstructions(undefined)).toBe(true);
	});

	it("requires them for schedules and windows", () => {
		expect(behaviorRequiresInstructions(schedule)).toBe(true);
		expect(
			behaviorRequiresInstructions([{ kind: "event", execution: "window" }]),
		).toBe(true);
	});

	it("does not require them for an event turn", () => {
		expect(behaviorRequiresInstructions(turn)).toBe(false);
	});
});

describe("validateBehaviorPrompt", () => {
	it("accepts prose alone when nothing is mentioned", () => {
		expect(
			validateBehaviorPrompt("Summarize yesterday.", LIBRARY, schedule),
		).toBeNull();
	});

	it("accepts a chip alone — the pinned body IS the instruction", () => {
		expect(validateBehaviorPrompt(chip("triage"), LIBRARY, schedule)).toBeNull();
	});

	it("requires something when the trigger runs on instructions alone", () => {
		expect(validateBehaviorPrompt("", LIBRARY, schedule)).toMatch(
			/Write what this Behavior should do/,
		);
		expect(validateBehaviorPrompt("   ", LIBRARY, schedule)).toMatch(
			/Write what this Behavior should do/,
		);
	});

	it("lets an event-turn Behavior run on the built-in default", () => {
		expect(validateBehaviorPrompt("", LIBRARY, turn)).toBeNull();
	});

	it("treats a source-chip-only prompt as having no instructions", () => {
		// A source chip is data, not an instruction, so it must not satisfy the
		// requirement the way a skill chip does. This regressed when `entity_type`
		// was added: the local strip regex matched `[a-z]+` for the kind, so the
		// underscored token survived stripping and the prompt looked like prose.
		expect(
			validateBehaviorPrompt(
				"@[entity_type:company:Companies](/acme/company)",
				LIBRARY,
				schedule,
			),
		).toMatch(/Write what this Behavior should do/);
	});

	it("rejects a chip whose skill left the library", () => {
		expect(validateBehaviorPrompt(chip("gone"), LIBRARY, schedule)).toMatch(
			/no longer in this agent's library/,
		);
	});

	it("rejects a disabled skill", () => {
		const lib = [skill("off", { enabled: false })];
		expect(validateBehaviorPrompt(chip("off"), lib, schedule)).toMatch(
			/disabled/,
		);
	});

	it("rejects an empty body", () => {
		const lib = [skill("blank", { content: "   " })];
		expect(validateBehaviorPrompt(chip("blank"), lib, schedule)).toMatch(
			/nothing to pin/,
		);
	});

	it("caps the number of mentioned skills", () => {
		const many = Array.from({ length: MAX_BEHAVIOR_SKILLS + 1 }, (_, i) =>
			skill(`s${i}`),
		);
		const prompt = many.map((s) => chip(s.name)).join(" ");
		expect(validateBehaviorPrompt(prompt, many, schedule)).toMatch(
			/the maximum is 5/,
		);
	});

	it("caps the pinned bytes", () => {
		const big = [
			skill("big", { content: "x".repeat(MAX_PINNED_SKILL_BYTES + 1) }),
		];
		expect(validateBehaviorPrompt(chip("big"), big, schedule)).toMatch(
			/the maximum is 32KB/,
		);
	});

	it("measures the cap in UTF-8 bytes, not characters", () => {
		// half+1 é chars: only 16385 CHARACTERS (comfortably under a char-based
		// cap of 32768) but 32770 BYTES — over. A char-counting implementation
		// passes this string; a byte-counting one rejects it.
		const half = MAX_PINNED_SKILL_BYTES / 2;
		const lib = [skill("multi", { content: "é".repeat(half + 1) })];
		expect(pinnedByteLength([{ name: "é", content: "é" }])).toBe(2);
		expect(validateBehaviorPrompt(chip("multi"), lib, schedule)).toMatch(
			/the maximum is 32KB/,
		);
	});
});

describe("selectableSkills", () => {
	it("keeps only enabled skills that carry a body", () => {
		const lib = [
			skill("ok"),
			skill("off", { enabled: false }),
			skill("blank", { content: "  " }),
		];
		expect(selectableSkills(lib).map((s) => s.name)).toEqual(["ok"]);
	});
});

describe("outdatedPinnedSkills", () => {
	const pinned: BehaviorSkillSnapshot[] = [
		{ name: "triage", content: "body of triage" },
	];

	it("finds a pin whose library body moved on", () => {
		const edited = [skill("triage", { content: "rewritten" })];
		expect(outdatedPinnedSkills(pinned, edited)).toEqual(["triage"]);
	});

	it("says nothing when the bodies still match", () => {
		expect(outdatedPinnedSkills(pinned, LIBRARY)).toEqual([]);
	});

	it("compares bodies, not names", () => {
		// A name-level diff reports "no changes" here and strands the Behavior on
		// the old text forever — the exact bug the snapshot model exists to fix.
		const edited = [skill("triage", { content: "body of triage v2" })];
		expect(outdatedPinnedSkills(pinned, edited)).toEqual(["triage"]);
	});

	it("does not call a deleted skill outdated", () => {
		// There is no newer text to take, and the pinned copy is what keeps the
		// Behavior running.
		expect(outdatedPinnedSkills(pinned, [])).toEqual([]);
	});
});

