export default async (ctx, client) => {
  const ops = await client.operations.listAvailable({ connection_id: 479 });
  return (ops.operations || []).map(o => o.operation_key).join(", ");
}

export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 479,
    operation_key: "navigate",
    input: { url: "http://localhost:5199/buremba/behaviors/new" },
  });
  const tab = nav.output?.tab_id;
  await ctx.sleep(9000);
  const r = await client.operations.execute({
    connection_id: 479,
    operation_key: "evaluate",
    input: { tab_id: tab, expression: `JSON.stringify({
      tabs: [...document.querySelectorAll('[role=tab],button')].map(b=>b.textContent.trim()).filter(Boolean).slice(0,25)
    })` },
  });
  return String(r.output?.value).slice(0, 900);
}

