  const nav = await client.operations.execute({
    connection_id: 479,
    operation_key: "navigate",
    input: { url: "http://localhost:5199/buremba/behaviors/new" },
  });
  const tab = nav.output?.tab_id;
  await ctx.sleep(9000);
  const r = await client.operations.execute({
    connection_id: 479,
    operation_key: "evaluate",
    input: { tab_id: tab, expression: `(() => {
      const el = [...document.querySelectorAll('[role=tab],button')].find(b=>b.textContent.trim()==='From scratch');
      if (el) el.click();
      return 'clicked:' + !!el;
    })()` },
  });
  await ctx.sleep(3500);
  const r2 = await client.operations.execute({
    connection_id: 479,
    operation_key: "evaluate",
    input: { tab_id: tab, expression: `JSON.stringify({
      hasAddSql: document.body.innerText.includes('Add SQL'),
      hasAddSource: document.body.innerText.includes('Add source'),
      hasSources: document.body.innerText.includes('Sources'),
      labels: [...document.querySelectorAll('label')].map(l=>l.textContent.trim()).slice(0,12),
      panel: document.body.innerText.slice(400, 1400)
    })` },
  });
  return JSON.stringify({ click: r.output?.value, panel: r2.output?.value }).slice(0, 2000);
}

