  const post = await client.operations.execute({
    connection_id: 479, operation_key: "evaluate",
    input: { tab_id: tab, expression:
      `fetch('http://127.0.0.1:5200/?name=after-1-fromscratch',{method:'POST',body:${JSON.stringify(dataUrl)}}).then(r=>r.status)` },
  });
  return "len=" + dataUrl.length + " post=" + JSON.stringify(post.output?.value);
}

