export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 479, operation_key: "navigate",
    input: { url: "http://localhost:5199/buremba/behaviors/new" },
  });
  const tab = nav.output?.tab_id;
  await ctx.sleep(11000);
  await client.operations.execute({
    connection_id: 479, operation_key: "evaluate",
    input: { tab_id: tab, expression: `(()=>{const el=[...document.querySelectorAll('[role=tab],button')].find(b=>b.textContent.trim()==='From scratch'); if(el) el.click(); return 1;})()` },
  });
  await ctx.sleep(5000);
  const typed = await client.operations.execute({
    connection_id: 479, operation_key: "evaluate",
    input: { tab_id: tab, expression: `(()=>{const pm=document.querySelector('.ProseMirror'); if(!pm) return 'NO_PM';
      pm.focus();
      const sel=window.getSelection(), range=document.createRange();
      range.selectNodeContents(pm); range.collapse(false); sel.removeAllRanges(); sel.addRange(range);
      document.execCommand('insertText', false, '@'); return 'ok:'+pm.textContent;})()` },
  });
  await ctx.sleep(4000);
  const state = await client.operations.execute({
    connection_id: 479, operation_key: "evaluate",
    input: { tab_id: tab, expression: `JSON.stringify({hasEntityType:/entity_type/.test(document.body.innerText), tail: document.body.innerText.slice(-350)})` },
  });
  const shot = await client.operations.execute({
    connection_id: 479, operation_key: "screenshot", input: { tab_id: tab },
  });
  const post = await client.operations.execute({
    connection_id: 479, operation_key: "evaluate",
    input: { tab_id: tab, expression: `fetch('http://127.0.0.1:5200/?name=before-2-atmenu',{method:'POST',body:${JSON.stringify(shot.output?.data_url)}}).then(r=>r.status)` },
  });
  return JSON.stringify({ typed: typed.output?.value, state: state.output?.value, post: post.output?.value }).slice(0, 1000);
}

