// Builds the self-contained before/after UI-proof page for `make ui-review`.
// Images are inlined here rather than pasted through the agent's context.
import { readFileSync, writeFileSync } from "node:fs";

const DIR = "/private/tmp/claude-501/-Users-burakemre-Code-lobu/3d24866b-b631-44fd-a5da-05ad63d65961/scratchpad";
const img = (n) =>
  `data:image/jpeg;base64,${readFileSync(`${DIR}/shots/${n}.jpg`).toString("base64")}`;

const shots = {
  before1: img("before-1-sources"),
  after1: img("after-1-fromscratch"),
  before2: img("before-2-atmenu"),
  after2: img("after-2-atmenu"),
};

const pair = (n, title, claim, before, after, beforeCap, afterCap) => `
<section class="pair">
  <div class="pair-head">
    <span class="idx">${n}</span>
    <div>
      <h2>${title}</h2>
      <p class="claim">${claim}</p>
    </div>
  </div>
  <div class="grid">
    <figure>
      <figcaption><span class="tag tag-before">Before</span> ${beforeCap}</figcaption>
      <a href="${before}" target="_blank" rel="noreferrer"><img src="${before}" alt="Before: ${beforeCap}"></a>
    </figure>
    <figure>
      <figcaption><span class="tag tag-after">After</span> ${afterCap}</figcaption>
      <a href="${after}" target="_blank" rel="noreferrer"><img src="${after}" alt="After: ${afterCap}"></a>
    </figure>
  </div>
</section>`;

const html = `<title>Behavior sources: @ is the one authoring gesture</title>
<style>
  :root {
    --paper: #fbfbfc; --panel: #ffffff; --ink: #16181d; --muted: #5f6672;
    --line: #e2e5ea; --accent: #1f6f5c; --add: #2f6b3f; --rm: #a3352b;
    --tag-before-bg: #f6e7e4; --tag-before-ink: #8e2f26;
    --tag-after-bg: #e2efe8; --tag-after-ink: #1c5f4a;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --paper: #0e1013; --panel: #161a1f; --ink: #e7e9ee; --muted: #98a0ae;
      --line: #262c34; --accent: #6fc0a8; --add: #7fc08f; --rm: #e3897e;
      --tag-before-bg: #3a2320; --tag-before-ink: #eda093;
      --tag-after-bg: #17362c; --tag-after-ink: #8ed7bd;
    }
  }
  :root[data-theme="dark"] {
    --paper: #0e1013; --panel: #161a1f; --ink: #e7e9ee; --muted: #98a0ae;
    --line: #262c34; --accent: #6fc0a8; --add: #7fc08f; --rm: #e3897e;
    --tag-before-bg: #3a2320; --tag-before-ink: #eda093;
    --tag-after-bg: #17362c; --tag-after-ink: #8ed7bd;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; background: var(--paper); color: var(--ink);
    font: 15px/1.6 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
    -webkit-font-smoothing: antialiased;
  }
  .wrap { max-width: 1180px; margin: 0 auto; padding: 40px 24px 72px; }
  header { border-bottom: 2px solid var(--ink); padding-bottom: 20px; margin-bottom: 8px; }
  .eyebrow {
    font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
    letter-spacing: .13em; text-transform: uppercase; color: var(--accent);
  }
  h1 { font-size: clamp(25px, 3.4vw, 37px); line-height: 1.12; margin: 12px 0 10px; letter-spacing: -.02em; text-wrap: balance; }
  .sub { color: var(--muted); max-width: 68ch; margin: 0; }
  .facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; margin: 26px 0 40px; }
  .fact { background: var(--panel); padding: 13px 15px; }
  .fact dt { font: 600 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); margin: 0 0 6px; }
  .fact dd { margin: 0; font: 13px/1.45 ui-monospace, Menlo, monospace; word-break: break-word; }
  .pair { margin: 0 0 46px; }
  .pair-head { display: flex; gap: 14px; align-items: flex-start; margin-bottom: 16px; }
  .idx { flex: none; width: 27px; height: 27px; border-radius: 50%; background: var(--accent); color: var(--paper); display: grid; place-items: center; font: 600 13px/1 ui-monospace, Menlo, monospace; margin-top: 2px; }
  .pair h2 { font-size: 19px; margin: 0 0 3px; letter-spacing: -.01em; }
  .claim { margin: 0; color: var(--muted); font-size: 14px; max-width: 78ch; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
  @media (max-width: 820px) { .grid { grid-template-columns: 1fr; } }
  figure { margin: 0; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
  figcaption { padding: 10px 13px; border-bottom: 1px solid var(--line); font-size: 12.5px; color: var(--muted); display: flex; gap: 9px; align-items: center; }
  .tag { font: 600 10px/1 ui-monospace, Menlo, monospace; letter-spacing: .09em; text-transform: uppercase; padding: 4px 7px; border-radius: 4px; }
  .tag-before { background: var(--tag-before-bg); color: var(--tag-before-ink); }
  .tag-after { background: var(--tag-after-bg); color: var(--tag-after-ink); }
  img { display: block; width: 100%; height: auto; }
  a { color: inherit; }
  .note { border-left: 3px solid var(--accent); background: var(--panel); border-radius: 0 8px 8px 0; padding: 15px 17px; margin: 0 0 40px; font-size: 14px; }
  .note h3 { margin: 0 0 7px; font-size: 14px; }
  .note code, .fact code { font-family: ui-monospace, Menlo, monospace; font-size: .93em; }
  .rm { color: var(--rm); } .add { color: var(--add); }
  ul.tight { margin: 8px 0 0; padding-left: 19px; } ul.tight li { margin: 4px 0; }
  footer { border-top: 1px solid var(--line); padding-top: 16px; color: var(--muted); font-size: 12.5px; }
</style>

<div class="wrap">
  <header>
    <div class="eyebrow">Owletto UI proof · Behaviors</div>
    <h1>Sources are authored with <code>@</code>, not with a second editor</h1>
    <p class="sub">The create form no longer carries its own Sources list. Every source — feed,
    connection, connector, metric, entity type, and inline SQL — is picked from the <code>@</code>
    menu inside the instructions, and compiled into <code>sources[]</code> on save.</p>
  </header>

  <dl class="facts">
    <div class="fact"><dt>Surface</dt><dd>/:org/behaviors/new → From scratch</dd></div>
    <div class="fact"><dt>Before</dt><dd>owletto <code>53aadfa3</code> (origin/main)</dd></div>
    <div class="fact"><dt>After</dt><dd>owletto <code>8b3e53bf</code></dd></div>
    <div class="fact"><dt>Captured against</dt><dd>vite dev → app.lobu.ai, org <code>buremba</code></dd></div>
  </dl>

  <div class="note">
    <h3>Why this pair also proves a dev-only regression is fixed</h3>
    <p style="margin:0">The <code>after</code> shots would not render at all without the fix in this
    branch. <code>@lobu/core</code> ships a CommonJS <code>dist</code>, and the new
    <code>@lobu/core/refs</code> subpath was imported for runtime values without being registered in
    <code>vite.config.ts</code>. Vite dev served it raw over ESM and the page died with
    <em>“does not provide an export named 'REF_TOKEN'”</em>. Every gate was structurally blind:</p>
    <ul class="tight">
      <li><code>tsc</code> resolves <code>dist/refs.d.ts</code>, which is correct</li>
      <li><code>vitest</code> runs in Node, where CJS → named-export interop works</li>
      <li><code>spa-boot-smoke</code> loads the <em>built</em> bundle, where <code>build.commonjsOptions</code> already applies</li>
    </ul>
    <p style="margin:8px 0 0">Only the dev server broke — which is where it was caught, by booting the page.</p>
  </div>

  ${pair(1, "The Sources editor is gone from create",
    "It was a second place to author the same thing, and the only route to a SQL source. Both jobs move into the @ menu.",
    shots.before1, shots.after1,
    "Advanced settings → Sources, with Add source and Add SQL",
    "No Sources section; the hint points at @")}

  ${pair(2, "@ now offers every source kind",
    "Before, a bare @ in the instructions returned No matches — source refs were gated off. After, it lists feeds, metrics, entity types and an inline SQL action.",
    shots.before2, shots.after2,
    "Typing @ → “No matches”",
    "Typing @ → feeds, metrics, entity types, SQL")}

  <footer>
    Captured in the user's signed-in Chrome via the paired Owletto extension. Both states rendered
    from the same booted app; only the owletto checkout differs between the two columns.
  </footer>
</div>`;

writeFileSync(`${DIR}/ui-proof.html`, html);
console.log(`wrote ui-proof.html ${(html.length / 1024 / 1024).toFixed(2)} MB`);

